From f16f6fe83de5fe53d5acffa5a0e831efcb21a50f Mon Sep 17 00:00:00 2001
From: Christopher Guindon <chris.guindon@eclipse-foundation.org>
Date: Wed, 18 Nov 2020 08:59:07 -0500
Subject: [PATCH 1/5] Remove cookie badge when a link is available

Signed-off-by: Christopher Guindon <chris.guindon@eclipse-foundation.org>
---
 js/solstice.cookieconsent.js | 3 +--
 1 file changed, 1 insertion(+), 2 deletions(-)

diff --git a/js/solstice.cookieconsent.js b/js/solstice.cookieconsent.js
index 49de2c36..8e6802c1 100644
--- a/js/solstice.cookieconsent.js
+++ b/js/solstice.cookieconsent.js
@@ -70,8 +70,7 @@ window.addEventListener("load", function() {
       }
     },
     onInitialise: function(status, options) {
-      var toolbar = document.getElementsByClassName("toolbar-manage-cookies");
-      if (toolbar.length <= 0) {
+      if (!document.getElementsByClassName("toolbar-manage-cookies").length) {
         setTimeout(function() {
           document.getElementsByClassName("cc-revoke")[0].style.display = "block";
         });

